        '<g transform="translate(720,380)"><rect x="-170" y="-65" width="340" height="130" rx="14" fill="#E4EBE5"/></g>'
        '<text x="1046" y="520" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="14" fill="#6E6A60" text-anchor="middle" dominant-baseline="central">to your best seller.</text>'
        '<text x="1046" y="496" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="14" fill="#6E6A60" text-anchor="middle" dominant-baseline="central">The trivial renewal given</text>'
