        '<text x="560" y="456" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="14" letter-spacing="1.4" fill="#6E6A60" text-anchor="middle" dominant-baseline="central">A FORMULA, NOT A FEATURE LIST</text>'
        '<text x="560" y="416" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="19" fill="#1A3B26" text-anchor="middle" dominant-baseline="central">When I do X to buyer Y, I produce outcome Z.</text>'
        '<text x="890" y="296" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="15" fill="#B9C7BC" text-anchor="middle" dominant-baseline="central">when and how it wins.</text>'
        '<text x="890" y="272" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="15" fill="#B9C7BC" text-anchor="middle" dominant-baseline="central">The repeatable equation for</text>'
        '<text x="890" y="224" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="22" letter-spacing="1.6" fill="#EDF2EE" text-anchor="middle" dominant-baseline="central">FORMULA</text>'
        '<text x="890" y="178" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="15" fill="#B9C7BC" text-anchor="middle" dominant-baseline="central">03</text>'
        '<text x="560" y="296" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="15" fill="#6E6A60" text-anchor="middle" dominant-baseline="central">deliberately as your one edge.</text>'
        '<text x="560" y="272" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="15" fill="#6E6A60" text-anchor="middle" dominant-baseline="central">That tool, chosen</text>'
        '<text x="560" y="224" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="22" letter-spacing="1.6" fill="#1A1A18" text-anchor="middle" dominant-baseline="central">WEAPON</text>'
        '<text x="560" y="178" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="15" fill="#6E6A60" text-anchor="middle" dominant-baseline="central">02</text>'
        '<text x="230" y="296" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="15" fill="#6E6A60" text-anchor="middle" dominant-baseline="central">happen to know.</text>'
        '<text x="230" y="272" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="15" fill="#6E6A60" text-anchor="middle" dominant-baseline="central">A methodology you</text>'
        '<text x="230" y="224" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="22" letter-spacing="1.6" fill="#1A1A18" text-anchor="middle" dominant-baseline="central">TOOL</text>'
        '<text x="230" y="178" font-family="Inter, system-ui, sans-serif" font-weight="700" font-size="15" fill="#6E6A60" text-anchor="middle" dominant-baseline="central">01</text>'
